/* CrewON Studio: local, self-contained product prototype. All production states and prices are demonstrative. */
'use strict';
const I=name=>studioIconArtwork[name]||studioIconArtwork.grid;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const app=document.getElementById('app');
const initialNodes=[
{id:'story',kind:'story',label:'故事与剧本',title:'末班灯',subtitle:'一个关于陌生人善意的故事',x:64,y:96,w:286,h:402,status:'已采用',frame:0},
{id:'actor',kind:'character',label:'角色',title:'林晚 · 旅人',description:'奶白风衣，棕色挎包。克制、疲惫，眼神里仍有期待。',x:414,y:96,w:248,h:298,status:'已采用',frame:1},
{id:'scene',kind:'scene',label:'场景',title:'旧站台 · 雨夜',description:'湿润路面，深青色夜景，一点暖光。',x:414,y:475,w:248,h:276,status:'已采用',frame:0},
{id:'shot1',kind:'shot',label:'镜头 01',title:'最后一班车',description:'远景 · 缓慢推进',x:762,y:96,w:286,h:297,status:'已采用',frame:0,seconds:8,dialogue:'末班车开走了，雨还没有停。',prompt:'雨夜的旧站台，末班车尾灯逐渐远去。镜头缓缓推进，留出人物所在的画面右侧。'},
{id:'shot2',kind:'shot',label:'镜头 02',title:'一盏灯的温度',description:'中景 · 轻推',x:1116,y:96,w:286,h:297,status:'待制作',frame:3,seconds:8,dialogue:'先照脚下，路就近了。',prompt:'守站人把一盏旧灯递给林晚，暖光照亮两人的手。中景，镜头轻轻推进，保留雨夜的青色背景。'},
{id:'shot3',kind:'shot',label:'镜头 03',title:'向着光走去',description:'跟拍 · 缓慢拉远',x:762,y:475,w:286,h:297,status:'待制作',frame:4,seconds:8,dialogue:'谢谢，我找到回家的路了。',prompt:'林晚提灯走进雨巷，回望站台后向前走。镜头平稳跟随再缓慢拉远，暖光留在画面中央。'},
{id:'shot4',kind:'shot',label:'镜头 04',title:'天亮之前',description:'远景 · 固定镜头',x:1116,y:475,w:286,h:297,status:'待制作',frame:5,seconds:6,dialogue:'有时候，回家的路只差一盏灯。',prompt:'黎明前的街口渐渐明亮，路面仍留着雨水的反光。固定远景，安静地结束。'},
{id:'final',kind:'final',label:'成片',title:'末班灯 · 第 1 集',description:'4 个镜头 · 30 秒 · 16:9',x:1518,y:227,w:294,h:315,status:'待合成',frame:4},
];
const defaultState={referenceProjectEdit:null,referenceCreationSpec:null,goal:'image',drafts:{},nodeDrafts:{},theme:'dark',projectKind:'drama',projectDrafts:{},canvasUndo:[],canvasRedo:[],toolCategory:0,screen:'home',intake:'idea',project:'末班灯',view:'canvas',scene:'all',selected:null,panel:'director',timeline:false,pan:{x:0,y:0},zoom:.75,mode:'select',approved:false,videoReady:false,spent:0,revision:1,nodes:initialNodes,edges:[['story','actor'],['story','scene'],['actor','shot1'],['actor','shot2'],['scene','shot3'],['scene','shot4'],['shot1','final'],['shot2','final'],['shot3','final'],['shot4','final']],clips:['shot1','shot2','shot3','shot4'],history:[],versions:{},imageSheet:'assets/stills.png'};
let stored={};try{stored=JSON.parse(studioStorage.getItem('crewon-studio-demo-v1')||'{}')}catch{};
let S={...structuredClone(defaultState),...stored,projectKind:stored.projectKind||'drama',screen:location.hash.includes('canvas')?'canvas':'home',pan:stored.pan||{x:0,y:0}};
// Retired soft-theme selections reuse the established dark palette.
if(S.theme==='eye')S.theme='dark';
if(S.canvasCreationLayout!==1){S.canvasCreationLayout=1;S.panel=null;}
if(!Array.isArray(stored.canvasUndo))S.canvasUndo=(S.history||[]).filter(h=>(h.id&&Number.isFinite(h.x)&&Number.isFinite(h.y))||h.type==='layout');
if(!Array.isArray(S.canvasRedo))S.canvasRedo=[];
let toastTimer,previewTimer,saveTimer,connecting=null,currentModal=null,previewTime=0,previewPlaying=false,drag=null;
const nodeById=id=>S.nodes.find(n=>n.id===id);
function persist(){studioStorage.setItem('crewon-studio-demo-v1',JSON.stringify({...S,screen:undefined}));document.querySelector('.saved')?.setAttribute('data-saved','true')}
function save(){clearTimeout(saveTimer);saveTimer=setTimeout(persist,200)}
function toast(text){const el=document.getElementById('toast');el.className='toast visible';el.textContent=text;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.className='toast',3300)}
const btn=(text,action,style='ghost',icon='')=>`<button class="button ${style}" data-action="${action}">${icon?I(icon):''}${text}</button>`;
const iconBtn=(label,action,icon,extra='')=>`<button class="icon-btn tip ${extra}" aria-label="${label}" data-action="${action}">${I(icon)}</button>`;
function rail(){return `<nav class="rail" aria-label="Studio 导航"><button class="brand-mark tip" aria-label="CrewON Studio" data-action="home">C</button>${[['home','首页','home'],['projects','项目','folder'],['assets','资产库','image'],['templates','创作模板','grid'],['experts','创作专家','people']].map(([a,l,i])=>`<button class="rail-btn tip ${((S.screen==='home'&&a==='home')||(S.screen==='canvas'&&a==='projects'))?'active':''}" data-action="${a}" aria-label="${l}">${I(i)}</button>`).join('')}<div class="rail-spacer"></div>${iconBtn('功能设计总览','features','layers')}${iconBtn('使用帮助','help','help')}${iconBtn('生成服务设置','settings','settings')}<button class="user-avatar" aria-label="当前账户 · CrewON 生态" data-action="ecosystem">CH</button></nav>`}
function header(){
 const canvas=S.screen==='canvas',drama=S.projectKind==='drama';
 return `<header class="topbar ${canvas?'project-topbar':''}"><button class="wordmark" data-action="home" aria-label="返回 Studio 首页">CrewON <span>STUDIO</span></button><span class="prototype-label">设计预览</span>${canvas?`<span class="divider"></span><div class="breadcrumb"><button data-action="home">我的项目</button>${I('chev')}<strong>${esc(S.project)}</strong>${drama?`${I('chev')}<span>第 1 集</span>`:''}</div>`:''}<div class="top-spacer"></div><span class="saved">${I('cloud')}此浏览器已保存</span><div class="top-actions">${iconBtn(S.theme==='light'?'切换深色主题':'切换浅色主题','toggle-theme','theme')}${canvas?`${iconBtn('项目记录','history','history')}${btn('预览','preview','outline','play')}${btn(drama?'导出':'交付','export','outline','download')}${btn(drama?(S.videoReady?'完成与交付':S.approved?'制作视频':'审阅制作方案'):(S.projectKind==='previs'?'审阅预演方案':S.projectKind==='interactive'?'审阅故事结构':'审阅创作方案'),drama?'next-stage':'review-project','primary','spark')}`:`${btn('生态能力','ecosystem','ghost','layers')}${btn('体验示例项目','open-example:drama','outline','arrow')}`}</div></header>`;
}
function home(){
 const recent=Object.values(S.projectDrafts).filter(d=>!studioExamples.some(e=>e.name===d.project)).reverse().map(d=>({name:d.project,key:d.projectKind,description:'本地创作草稿 · 可继续编辑',frame:d.nodes.find(n=>mediaKind(n)==='image')?.frame||0,action:'继续编辑',resume:true}));
 return `<main class="home"><div class="home-inner"><div class="home-intro"><div><div class="eyebrow">YOUR NEXT WORK STARTS HERE</div><h1><span>从一个想法，</span><span>到一部作品。</span></h1><p>说说想完成什么，或带上已有内容。创作团队会先整理方案，再开始制作。</p></div></div>
 <section class="create-box goal-composer" aria-label="开始一份作品"><div class="composer-hint">你想做一部什么作品？</div><textarea id="idea-input" aria-label="作品想法" placeholder="例如：把这个雨夜车站的故事，做成一部 30 秒的温暖短片。希望先看分镜预览，再决定怎么拍。">${esc(S.drafts.shared||'')}</textarea><div class="create-controls">${btn('添加素材','upload','ghost','plus')}${btn('制作偏好','work-preferences','ghost','sliders')}<span class="composer-save-note">先规划，再制作</span>${btn('整理制作方案','start','primary','arrow')}</div></section>
 <div class="example-row"><span>也可以从这里开始：</span><button data-action="import-start:script">已有剧本</button><i class="sep"></i><button data-action="import-start:reference">参考作品</button><i class="sep"></i><button data-action="open-example:blank">空白画布</button></div>
 <div class="section-head"><h2>我的项目</h2><div class="section-tools"><input type="search" id="project-search" aria-label="搜索项目" placeholder="搜索项目…">${iconBtn('新建空白画布','open-example:blank','plus')}</div></div>
 <div class="project-grid" id="project-grid">${studioExamples.map(item=>`<button class="project-card" data-action="open-example:${item.key}"><span class="cover still frame${item.frame}"><span class="cover-title">${item.name}</span><span class="pill">${item.action}</span></span><div class="project-caption"><div><h3>${item.name}</h3><p>${item.description}</p></div><span class="caption-date">示例项目</span></div></button>`).join('')}</div>
 ${recent.length?`<details class="recent-drafts"><summary>继续本地草稿 <span>${recent.length}</span></summary><div class="draft-list">${recent.map(d=>`<button data-action="resume-project:${esc(d.name)}">${I('folder')}<span>${esc(d.name)}</span>${I('chev')}</button>`).join('')}</div></details>`:''}
 <div class="section-head"><h2>不知道怎么开始？先选一份制作方案。</h2>${btn('查看创作能力','all-tools','ghost','chev')}</div><div class="template-grid">${[['drama','把故事做成短片','剧本、角色、分镜与剪辑，逐步完成。',0],['previs','先试一试镜头','先确定空间、动作和机位，减少重做。',4],['interactive','让观众参与故事','用选择连接情节，比较不同结局。',5]].map(([key,title,description,frame])=>`<button class="template-card" data-action="plan-template:${key}"><span class="template-thumb still frame${frame}"></span><span><h3>${title}</h3><p>${description}</p></span>${I('chev')}</button>`).join('')}</div>
 <div class="home-principles"><span>${I('check')}先看预览</span><span>${I('layers')}优先复用素材</span><span>${I('edit')}只重做需要调整的部分</span></div><footer class="home-footer"><span>${I('layers')}与 CrewON 共用专家、工具与项目</span><span>设计预览 · 示例内容不调用生成服务</span></footer></div></main>`;
}
function projectNav(){
 if(S.projectKind==='drama')return scriptProjectNav();
 return `<aside class="project-nav" aria-label="项目内容"><div class="project-name">${I('folder')}<strong>${esc(S.project)}</strong></div><button class="tree-item active" data-action="fit">${I('grid')}画布总览</button><div class="nav-label">项目内容</div>${S.nodes.map(n=>`<button class="tree-item" data-focus="${n.id}">${I(kindIcon[n.kind]||'file')}<span>${esc(n.title)}</span></button>`).join('')}<div class="nav-spacer"></div><button class="tree-item" data-action="assets">${I('image')}项目资产</button><button class="tree-item" data-action="history">${I('history')}版本与记录</button><button class="tree-item" data-action="all-tools">${I('layers')}创作工具</button></aside>`;
}
const kindIcon={camera:'film',choice:'file',ending:'play',image:'image',video:'film',audio:'mic',text:'file',story:'file',character:'user',scene:'scene',shot:'film',final:'play',voice:'mic',note:'file'};
function nodeDisplay(n){
 const candidates=ensureCandidateHistory(n),output=candidates.find(c=>c.id===n.adoptedCandidateId);
 return output?{...n,frame:output.frame,seconds:output.seconds,dialogue:output.dialogue,description:output.description}:n;
}
function projectClips(){return S.clips.map(nodeById).filter(Boolean).map(nodeDisplay)}
function projectDuration(){return projectClips().reduce((sum,n)=>sum+(n.seconds||0),0)}
function sceneBreakTime(){return projectClips().slice(0,2).reduce((sum,n)=>sum+(n.seconds||0),0)}
function timeLabel(seconds){return String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(Math.floor(seconds%60)).padStart(2,'0')}
function nodeStageLabel(n){
 if(n.reviewRequired)return '待复核';if(n.referenceOnly)return '待制作';if(!['制作中','生成失败'].includes(n.status)&&studioAssetReferenceChanges(nodeById(n.id)||n).length)return '参考可更新';
 const adopted=studioAdoptedCandidate(n);
 return adopted?.createdAt&&!['制作中','已完成','生成失败'].includes(n.status)?'已采用':n.status;
}
function nodeHtml(n){n=nodeDisplay(n);if(n.kind==='final')n={...n,seconds:projectDuration(),description:S.clips.length+' 个镜头 · '+projectDuration()+' 秒 · 16:9'};const selected=S.selected===n.id,tag=['待复核','待制作','待合成','参考可更新'].includes(nodeStageLabel(n))?'pending':nodeStageLabel(n)==='生成失败'?'failed':'';let body='';if(n.kind==='camera'){body=cameraNodeBody(n)}else if(n.kind==='choice'){body=choiceNodeBody(n)}else if(['note','text'].includes(n.kind)){body=`<div class="node-content node-text"><h3>${esc(n.title)}</h3><p>${esc(n.text||n.prompt||n.description||'在右侧编辑内容')}</p></div>`}else if(n.kind==='story'){body=scriptNodeBody(n)}else if(['voice','audio'].includes(n.kind)){body=`<div class="node-sound">${I('mic')}<div class="waveform">${Array.from({length:28},(_,i)=>`<i style="--h:${6+(i*17%23)}px"></i>`).join('')}</div></div><div class="node-content"><h3>${esc(n.title)}</h3><p>${esc(n.description||'声音稿与候选')}</p></div>`}else if(n.referenceOnly){body=`<div class="node-media pending-media">${I(kindIcon[n.kind]||'image')}<span>尚未制作</span></div><div class="node-content"><h3>${esc(n.title)}</h3><p>${esc(n.prompt||n.description||'先确认镜头内容')}</p></div><footer class="node-footer">${I('file')}<span>${n.kind==='shot'?'镜头输入':'内容草稿'} · 暂无采用结果</span></footer>`}else{body=`<div class="node-media still frame${n.frame}">${['shot','video','final'].includes(n.kind)?`<span class="play-badge">${I(n.status==='已完成'?'play':'image')}${n.kind==='video'?'视频示意':n.status==='已完成'?'视频':'关键帧'}</span><span class="duration">${n.seconds||30}s</span>`:''}</div><div class="node-content"><h3>${esc(n.title)}</h3><p>${esc(n.description||'新的创作素材')}</p></div><footer class="node-footer">${I(n.kind==='shot'?'link':'check')}<span>${n.kind==='shot'?esc(scriptShotSourceLabel(n)):'采用 v'+candidateVersion(n)+' · 已保存'}</span><span class="spacer"></span>${n.kind==='shot'?'<span>v'+candidateVersion(n)+'</span>':''}</footer>`}return `<article class="node ${n.kind==='story'?'script-node':''} ${selected?'selected':''}" tabindex="0" data-node="${n.id}" aria-label="${esc(n.label+' · '+n.title)}" style="left:${n.x}px;top:${n.y}px;width:${n.w}px;min-height:${n.h}px"><div class="node-actions">${iconBtn('打开属性','select:'+n.id,'sliders')}${iconBtn('复制节点','duplicate:'+n.id,'copy')}${ensureCandidateHistory(n).length?iconBtn('查看版本','versions:'+n.id,'history'):''}</div><header class="node-header" data-drag="${n.id}"><span class="node-kind">${I(kindIcon[n.kind])}${esc(n.label)}</span><span class="node-tag ${tag}">${n.status==='制作中'&&!n.reviewRequired?'<i class="loading-spinner"></i>':esc(nodeStageLabel(n))}</span></header>${body}${canvasNodeReferenceShortcuts(n)}<button class="port in" data-port-in="${n.id}" aria-label="连接到${esc(n.title)}"></button><button class="port out ${connecting===n.id?'connecting':''}" data-port-out="${n.id}" aria-label="从${esc(n.title)}开始连线"></button></article>`}
function canvasLabels(){
 if(S.nodes.some(node=>node.id==='previs-plan'||node.id==='interactive-plan'))return '';
 const labels=({previs:['镜头意图','场景参考','机位与构图'],interactive:['故事主线','开场画面','选择与结局'],blank:[]})[S.projectKind]||['创作目标',S.projectKind==='audio'?'声音稿':'参考素材','候选与调整'];
 return labels.map((label,i)=>`<div class="world-label" style="left:${[96,440,805][i]}px;top:52px">${label}</div>`).join('');
}
function canvasHtml(){return `<section class="studio-body">${S.outlineOpen?canvasOutlineHtml():''}<section class="canvas-shell" aria-label="制作画布"><header class="canvas-top"><div class="segmented" role="tablist" aria-label="工作视图"><button role="tab" aria-selected="${S.view==='canvas'}" data-view="canvas" class="${S.view==='canvas'?'active':''}">无限画布</button><button role="tab" aria-selected="${S.view==='storyboard'}" data-view="storyboard" class="${S.view==='storyboard'?'active':''}">${S.projectKind==='drama'?'分镜视图':'内容列表'}</button></div>${S.projectKind==='drama'?scriptSceneTabs():''}<div class="canvas-actions">${iconBtn('自动整理画布','layout','layout')}${['drama','video'].includes(S.projectKind)?iconBtn('打开时间线','timeline','film'):''}<button class="button ${S.panel==='director'?'secondary':'ghost'}" data-action="director">${I('spark')}${S.projectKind==='drama'?'导演助手':'创作助手'}</button></div></header><div class="canvas-viewport" id="viewport" tabindex="0" aria-label="无限画布，可拖动空白处平移" aria-keyshortcuts="ArrowUp ArrowDown ArrowLeft ArrowRight"><div class="canvas-world" id="world">${S.projectKind==='drama'?`<div id="script-groups">${scriptCanvasGroups()}</div>`:canvasLabels()}<svg class="connections" id="connections" aria-label="内容引用与组合关系"></svg><div id="nodes">${S.nodes.map(nodeHtml).join('')}</div></div>${S.view==='storyboard'?storyboardHtml():''}${selectionToolbar()}${canvasCreationHtml()}<div class="floating-tools" aria-label="画布工具">${iconBtn('项目目录','canvas-outline','folder')}${iconBtn('选择与拖动节点','tool-select','pointer',S.mode==='select'?'active':'')}${iconBtn('拖动画布','tool-pan','hand',S.mode==='pan'?'active':'')}<div class="tool-sep"></div>${iconBtn('添加创作节点','add-node','plus')}${iconBtn('引用资产','assets','image')}${iconBtn('整理画布','layout','layout')}<div class="tool-sep"></div>${canvasHistoryButtonsHtml()}${iconBtn('画布操作帮助','help','help')}</div><div class="canvas-prototype-note">原型画布 · 拖动 / 缩放 / 连线可操作</div><div class="canvas-help"><kbd>Space</kbd>拖动平移　<span>⌘ / Ctrl + 滚轮缩放</span>　<span>F 适应全部</span></div><div class="canvas-bottom"><div class="minimap" id="minimap" aria-label="画布缩略图"></div><div class="zoom-control"><button class="map-toggle" data-action="canvas-nav-map" aria-pressed="${canvasNavigatorState().mapVisible}" aria-label="切换小地图">小地图</button>${iconBtn('缩小画布','zoom-out','minus')}<button class="zoom-label" data-action="reset-zoom" aria-label="重置为百分之百">${Math.round(S.zoom*100)}%</button>${iconBtn('放大画布','zoom-in','plus')}${iconBtn('适应全部节点','fit','fit')}</div></div></div>${S.timeline?timelineHtml():''}</section>${S.panel?inspectorHtml():''}</section>`}
function storyboardHtml(){const nodes=(S.projectKind==='drama'?S.nodes.filter(n=>n.kind==='shot'):S.nodes).map(nodeDisplay);return `<div class="storyboard-list"><h2>${S.projectKind==='drama'?'按镜头查看故事':'项目中的所有内容'}</h2><p>同一份项目与采用记录，切换视图继续编辑。</p><div class="shot-table">${nodes.map(n=>`<button class="shot-table-card" data-select="${n.id}">${n.referenceOnly?`<div class="list-type-icon pending-media">${I('film')}<span>尚未制作</span></div>`:['text','note','voice','audio'].includes(n.kind)?`<div class="list-type-icon">${I(kindIcon[n.kind])}</div>`:`<div class="still frame${n.frame}"></div>`}<div class="shot-caption"><h3>${esc(n.title)}</h3><p>${esc(n.dialogue||n.description||n.text||n.label)}</p><span class="pill">${esc(n.label)} · ${esc(n.status)}</span></div></button>`).join('')}</div></div>`}
function directorHtml(){if(S.projectKind!=='drama')return genericDirector();const doc=studioScriptNode()?.scriptDocument;return `<div class="director-header"><div class="director-avatar">${I('spark')}</div><div><h3>导演助手</h3><p>连接 CrewON 专家与工具</p></div></div><p class="director-message">${esc(doc?.logline||'先确认故事和人物，再开始制作。')}<br>当前剧本 <strong>${doc?.scenes.length||0} 场、${S.clips.length} 个镜头</strong>，先审阅预览，再安排制作。</p><div class="plan-card"><div class="plan-card-head">${I('layers')}本集制作方案<span class="pill" style="margin-left:auto;font-size:9px">${projectDuration()} 秒</span></div><section><div class="plan-line done"><span class="plan-number">${I('check')}</span><span>故事与角色</span><span class="state">已采用</span></div><div class="plan-line ${S.approved?'done':'active'}"><span class="plan-number">2</span><span>低成本分镜预览</span><span class="state">${S.approved?'已确认':'待确认'}</span></div><div class="plan-line ${S.approved&&!S.videoReady?'active':S.videoReady?'done':''}"><span class="plan-number">3</span><span>视频与配音</span><span class="state">${S.videoReady?'已完成':S.approved?'待制作':'稍后确认'}</span></div><div class="plan-line ${S.videoReady?'active':''}"><span class="plan-number">4</span><span>剪辑与成片</span><span class="state">${S.videoReady?'可预览':'尚未开始'}</span></div><div class="plan-cost"><span>下一阶段预估</span><strong>${S.videoReady?'已就绪':S.approved?'¥15.40':'¥3.20'}</strong></div></section>${btn(S.videoReady?'预览成片':S.approved?'确认视频制作':'审阅并确认预览',S.videoReady?'preview':S.approved?'approve-video':'approve-preview','primary',S.videoReady?'play':'arrow')}<p style="font-size:9px;color:var(--muted);padding:0 12px 12px;line-height:1.5">示例估算 · 确认前不会启动下一阶段</p></div><p class="director-note">${I('shield')}只重做需要修改的镜头。已采用的角色和场景会继续复用。</p><div style="margin-top:19px;display:flex;gap:6px;flex-wrap:wrap">${btn('画面更温暖','suggest-warm','outline')}${btn('压缩制作成本','budget','outline')}</div>`}
function selectionHtml(n){
 if(!n)return directorHtml();if(n.kind==='story')return scriptProperties(n);if(n.kind==='choice')return choiceProperties(n);const kind=mediaKind(n),textual=kind==='text',sound=kind==='audio',adopted=ensureCandidateHistory(n).find(c=>c.id===n.adoptedCandidateId),videoBinding=kind==='video'?referenceVideoBinding(canvasCreationDraft(n)):null;
 const groups=studioTools[kind],tools={image:['参考图编辑','局部重绘','扩图','画质增强'],video:['图片生成视频','视频续写','片段重拍','视频超分'],audio:['文字配音','氛围音乐','音乐续写','音轨提取'],text:groups[0].items.slice(0,4)}[kind];
 return `${scriptReviewNotice(n)}<h2 class="inspector-title">${esc(n.title)}</h2><p class="inspector-sub">${esc(n.label)} · ${adopted?'当前采用 v'+adopted.number+(kind==='video'&&adopted.seconds?' · '+adopted.seconds+' 秒':''):esc(n.status)}</p>${adopted?'<div class="input-edit-heading"><span>下一次制作</span><small>修改输入，不改变当前采用结果</small></div>':''}
 <label class="field">${textual?'文字内容':sound?'声音描述':kind==='video'?'画面与动作':'画面描述'}<textarea id="node-prompt">${esc(S.nodeDrafts[n.id]?.prompt??n.text??n.prompt??n.description??'')}</textarea></label>
 ${kind==='video'&&videoBinding?`<div class="ref-video-editor-summary"><span>${esc(videoBinding.error||videoBinding.family.label)}</span>${!videoBinding.error?`<small>${referenceVideoExecutionSettings(n,canvasCreationDraft(n)).seconds?'当前制作时长 '+referenceVideoExecutionSettings(n,canvasCreationDraft(n)).seconds+' 秒':'时长由输入素材与模型决定'}</small>`:''}${btn('在画布调整模型参数','canvas-creation-video-parameters','outline','settings')}</div>`:kind==='video'?`<div class="field-grid"><label class="field">镜头时长<select id="node-duration">${[4,6,8,10,12].map(v=>`<option value="${v}" ${Number(S.nodeDrafts[n.id]?.seconds??n.seconds)===v?'selected':''}>${v} 秒</option>`).join('')}</select></label><label class="field">镜头运动<select id="node-motion">${['缓慢推进','平稳跟拍','固定镜头','缓慢拉远'].map(m=>`<option ${(S.nodeDrafts[n.id]?.motion??n.motion)===m?'selected':''}>${m}</option>`).join('')}</select></label></div><label class="field">对白 / 旁白<input id="node-dialogue" value="${esc(S.nodeDrafts[n.id]?.dialogue??n.dialogue??'')}"></label>`:''}
 ${sound?`<div class="field-grid">${[['表达方式','creationExpression',['自然旁白','角色对白','氛围音乐']],['语速','creationPace',['自然','舒缓','轻快']]].map(([label,key,values])=>`<label class="field">${label}<select aria-label="${label}" data-creation-setting="${key}">${values.map(value=>`<option ${value===(canvasCreationDraft(n)[key]||values[0])?'selected':''}>${value}</option>`).join('')}</select></label>`).join('')}</div>`:''}
 <div class="inspector-buttons">${btn('保存修改','save-node','outline','check')}${btn(textual?'请助手修改':n.candidates?.length?'准备新候选':'准备首个候选',textual?'director':'candidate-prepare:'+n.id,'primary','spark')}</div>
 <details class="editor-disclosure"><summary>更多创作工具</summary><div class="context-tools"><div class="context-label"><span>用这份内容继续创作</span><button class="button ghost" data-action="all-tools">全部${I('chev')}</button></div><div class="quick-tool-grid">${tools.map(t=>`<button class="quick-tool" data-action="tool:${t}">${I(kind==='image'?'image':kind==='video'?'film':sound?'mic':'edit')}<span>${t}</span></button>`).join('')}</div></div></details>
 <details class="editor-disclosure"><summary>参考与使用位置</summary>${assetUsageSectionHtml(n)}${assetReferenceSectionHtml(n)}</details><details class="editor-disclosure"><summary>候选与版本 · ${n.candidates?.length||0}</summary>${candidateSectionHtml(n)}</details>`;
}
function inspectorHtml(){const n=nodeById(S.selected);return `<aside class="inspector" aria-label="${S.panel==='director'?'创作助手':'节点属性'}"><header class="inspector-head"><span>${S.panel==='director'?'创作助手':'内容属性'}</span><div style="display:flex;gap:5px">${S.panel!=='director'?iconBtn('返回创作助手','director','spark'):''}${iconBtn('收起右侧面板','close-panel','close')}</div></header><div class="inspector-content">${S.panel==='director'?directorHtml():selectionHtml(n)}</div>${S.panel==='director'?`<div class="chat-input-wrap"><form class="chat-input" id="director-form"><textarea aria-label="与创作助手对话" placeholder="告诉助手，你想调整哪里…"></textarea><footer><span>只改你指定的部分</span><button type="submit" class="icon-btn" aria-label="发送给创作助手">${I('arrowup')}</button></footer></form></div>`:''}</aside>`}
function timelineHtml(){
 const clips=projectClips(),duration=projectDuration(),ticks=Array.from({length:Math.floor(duration/4)+1},(_,i)=>timeLabel(i*4));
 return `<section class="timeline" aria-label="剪辑时间线"><header class="timeline-head">${I('film')}<span>本集剪辑</span><span class="timeline-count">${clips.length} 个镜头 · ${timeLabel(duration)}</span><div class="timeline-actions">${iconBtn('预览时间线','preview','play')}<span class="mono timeline-clock">00:00 / ${timeLabel(duration)}</span>${btn('字幕与声音','audio','ghost','mic')}${iconBtn('收起时间线','timeline','down')}</div></header><div class="timeline-body"><div class="ruler">${ticks.map(v=>`<span>${v}</span>`).join('')}</div><span class="track-label video">画面</span><span class="track-label audio">声音</span><div class="video-track" style="grid-template-columns:${clips.map(n=>(n.seconds||1)+'fr').join(' ')}">${clips.map(n=>`<div class="clip ${n.referenceOnly?'pending-clip':'still frame'+n.frame} ${S.selected===n.id?'active':''}" draggable="true" data-clip="${n.id}" aria-label="时间线镜头 ${esc(n.title)}" tabindex="0"><span>${esc(n.label)} · ${n.seconds}s · ${n.referenceOnly?'待制作':'v'+candidateVersion(n)}</span><div class="clip-actions"><button data-moveclip="${n.id}" data-direction="-1" aria-label="前移${esc(n.title)}">←</button><button data-moveclip="${n.id}" data-direction="1" aria-label="后移${esc(n.title)}">→</button></div></div>`).join('')}</div><div class="audio-track">${I('mic')}对白与环境声 · ${duration} 秒</div><div class="playhead"></div></div></section>`;
}
function render(){S.nodes.forEach(ensureCandidateHistory);S.nodes.filter(n=>['shot','video','image'].includes(n.kind)).forEach(ensureStudioAssetReferences);if(typeof studioNativeApplyTheme==='function'&&parent!==window)studioNativeApplyTheme();else{document.documentElement.dataset.theme=S.theme==='light'?'light':'dark';document.body.toggleAttribute('data-ds-dark-theme',S.theme!=='light');}document.documentElement.dataset.studioTheme=S.theme;app.innerHTML=`<div class="shell">${rail()}<div class="workspace">${header()}${S.screen==='home'?home():canvasHtml()}</div></div>`;if(S.screen==='canvas'){drawEdges();applyCamera();setupCanvas();refreshCanvasCreation();restoreCanvasNavigator()}save()}
function openProject(name=S.project){
 rememberProject();
 const preset=studioExamples.find(x=>x.name===name);
 if(preset&&preset.key!==S.projectKind){loadStudioExample(preset.key);return}
 S.project=name;S.screen='canvas';S.selected=null;S.panel=null;S.view='canvas';S.scene='all';location.hash='canvas';render();setTimeout(()=>fitCanvas(false),35);
}
function drawEdges(){const svg=document.getElementById('connections');if(!svg)return;svg.innerHTML=S.edges.map(([from,to])=>{const source=nodeById(from),target=nodeById(to),path=canvasLinkPath(from,to);if(!path)return '';const selected=canvasSelectedLink?.from===from&&canvasSelectedLink?.to===to;return `<g><path class="${selected?'canvas-edge-selected':from===S.selected||to===S.selected?'selected-edge':''}" d="${path.d}"/><path class="canvas-link-hit" role="button" tabindex="0" data-link-from="${esc(from)}" data-link-to="${esc(to)}" aria-label="连接：${esc(source.title)} → ${esc(target.title)}" d="${path.d}"/></g>`}).join('');canvasLinkPanelSync()}

function applyCamera(){document.querySelector('.canvas-followup-menu')?.remove();const world=document.getElementById('world'),viewport=document.getElementById('viewport');if(!world||!viewport)return;viewport.classList.toggle('zoom-overview',S.zoom<.68);world.style.setProperty('--canvas-inverse-zoom',1/S.zoom);world.style.transform=`translate(${S.pan.x}px,${S.pan.y}px) scale(${S.zoom})`;viewport.style.backgroundPosition=`${S.pan.x}px ${S.pan.y}px`;viewport.style.backgroundSize=`${22*S.zoom}px ${22*S.zoom}px`;document.querySelector('.zoom-label').textContent=Math.round(S.zoom*100)+'%';const groups=document.getElementById('script-groups');if(groups)groups.innerHTML=scriptCanvasGroups();drawEdges();syncCanvasRecovery();drawMinimap();positionSelectionToolbar()}
function minimapMapping(){
 const map=document.getElementById('minimap'),viewport=document.getElementById('viewport');
 if(!map||!viewport)return null;
 const view={x:-S.pan.x/S.zoom,y:-S.pan.y/S.zoom,w:viewport.clientWidth/S.zoom,h:viewport.clientHeight/S.zoom};
 const rects=S.nodes.map(n=>({x:n.x,y:n.y,w:n.w,h:document.querySelector(`[data-node="${n.id}"]`)?.offsetHeight||n.h}));
 const all=[view,...rects],padding=100;
 const minX=Math.min(...all.map(n=>n.x))-padding,minY=Math.min(...all.map(n=>n.y))-padding;
 const width=Math.max(...all.map(n=>n.x+n.w))+padding-minX,height=Math.max(...all.map(n=>n.y+n.h))+padding-minY;
 const scale=Math.min(map.clientWidth/width,map.clientHeight/height);
 return {view,rects,minX,minY,scale,offsetX:(map.clientWidth-width*scale)/2,offsetY:(map.clientHeight-height*scale)/2};
}
function drawMinimap(){
 const m=document.getElementById('minimap'),layout=minimapMapping();if(!m||!layout)return;
 const {view,rects,minX,minY,scale,offsetX,offsetY}=layout;
 const css=r=>`left:${offsetX+(r.x-minX)*scale}px;top:${offsetY+(r.y-minY)*scale}px;width:${r.w*scale}px;height:${r.h*scale}px`;
 m.innerHTML=rects.map((r,i)=>`<span class="mini-node ${S.nodes[i].id===S.selected?'selected':''}" style="${css(r)}"></span>`).join('')+`<span class="mini-viewport" style="${css(view)}"></span>`;
}
function selectionToolbar(){
 const n=nodeById(S.selected);if(!n||S.view!=='canvas')return '';
 if(canvasCreationNode()&&S.panel!=='selection')return canvasContextToolbar(n);
 const media=studioCandidateKinds.has(n.kind),refs=studioAssetTargetKinds.has(n.kind);
 return `<div class="selection-toolbar" role="toolbar" aria-label="选中内容操作">${btn('编辑','edit-node:'+n.id,'ghost','edit')}${media?btn('制作','candidate-prepare:'+n.id,'primary','spark'):''}${refs?btn('参考 '+studioAssetReferenceSnapshot(n).length,'asset-picker:'+n.id,'ghost','image'):''}${media&&n.candidates?.length?btn('版本 '+n.candidates.length,'candidate-review:'+n.id,'ghost','history'):''}<details class="node-more"><summary role="button" aria-label="更多内容操作">更多</summary><div>${btn('定位内容','focus-node:'+n.id,'ghost','fit')}${btn('复制内容','duplicate:'+n.id,'ghost','copy')}${btn('创作工具','all-tools','ghost','layers')}</div></details></div>`;
}
function positionSelectionToolbar(){
 const bar=document.querySelector('.selection-toolbar'),node=document.querySelector(`[data-node="${S.selected}"]`),vp=document.getElementById('viewport');if(!node||!vp)return;
 if(!bar){if(canvasCreationNode())positionCanvasNodeOverlays();return;}
 if(bar.classList.contains('creation-toolbar')){positionCanvasNodeOverlays();return;}
 const r=node.getBoundingClientRect(),v=vp.getBoundingClientRect();
 bar.style.left=Math.max(12,Math.min(v.width-bar.offsetWidth-12,r.left-v.left+(r.width-bar.offsetWidth)/2))+'px';
 const headerBottom=document.querySelector('.ref-canvas-header')?.getBoundingClientRect().bottom??v.top;
 const minTop=Math.max(12,headerBottom-v.top+8),maxTop=Math.max(minTop,v.height-bar.offsetHeight-12),above=r.top-v.top-bar.offsetHeight-12,below=r.bottom-v.top+12;
 const top=Math.max(minTop,Math.min(maxTop,above<minTop&&below<=maxTop?below:above));bar.style.top=top+'px';bar.classList.toggle('toolbar-menu-up',v.height-top-bar.offsetHeight<160&&top>160);
}
function revealSelectedNode(){
 const n=nodeById(S.selected),viewport=document.getElementById('viewport'),el=n&&document.querySelector(`[data-node="${n.id}"]`);if(!n||!viewport||!el)return;
 const viewportRect=viewport.getBoundingClientRect(),obstacles=[document.querySelector('.canvas-navigator'),document.querySelector('.floating-tools')].filter(el=>el&&el.getBoundingClientRect().width>0);
 const left=Math.max(72,...obstacles.map(el=>el.getBoundingClientRect().right-viewportRect.left+12)),top=72,right=viewport.clientWidth-20,bottom=viewport.clientHeight-(canvasCreationNode()?300:104);
 const x=S.pan.x+n.x*S.zoom,y=S.pan.y+n.y*S.zoom,w=n.w*S.zoom,h=el.offsetHeight*S.zoom;
 if(w>right-left)S.pan.x+=left-x;else if(x<left)S.pan.x+=left-x;else if(x+w>right)S.pan.x+=right-x-w;
 if(h>bottom-top)S.pan.y+=top-y;else if(y<top)S.pan.y+=top-y;else if(y+h>bottom)S.pan.y+=bottom-y-h;
 applyCamera();
}
function fitCanvas(all=true){
 const viewport=document.getElementById('viewport');if(!viewport)return;
 if(!all){S.zoom=Math.max(.55,Math.min(.9,(viewport.clientWidth-100)/1120));S.pan={x:78-48*S.zoom,y:48};applyCamera();save();return;}
 if(!S.nodes.length){S.zoom=.9;S.pan={x:80,y:80};applyCamera();save();return;}
 const minX=Math.min(...S.nodes.map(n=>n.x)),minY=Math.min(...S.nodes.map(n=>n.y)),maxX=Math.max(...S.nodes.map(n=>n.x+n.w)),maxY=Math.max(...S.nodes.map(n=>n.y+(document.querySelector(`[data-node="${n.id}"]`)?.offsetHeight||n.h)));
 const width=Math.max(1,maxX-minX),height=Math.max(1,maxY-minY),usableWidth=Math.max(1,viewport.clientWidth-112),usableHeight=Math.max(1,viewport.clientHeight-144);
 S.zoom=Math.min(.9,usableWidth/width,usableHeight/height);
 S.pan={x:80+(usableWidth-width*S.zoom)/2-minX*S.zoom,y:80+(usableHeight-height*S.zoom)/2-minY*S.zoom};
 applyCamera();save();
}
function focusNode(id){S.view='canvas';const n=nodeById(id),v=document.getElementById('viewport');if(!n||!v)return;if(v.clientWidth<=720)S.outlineOpen=false;canvasSelectedLink=null;S.selected=id;S.panel=(studioCandidateKinds.has(n.kind)&&n.kind!=='final')||referenceCutKinds.has(n.kind)?null:'selection';render();const now=document.getElementById('viewport'),usableHeight=now.clientHeight-(document.querySelector('.canvas-creation')?.offsetHeight||0)-30;S.zoom=Math.max(.5,Math.min(.95,(usableHeight-60)/(n.h+40)));S.pan={x:(now.clientWidth-n.w*S.zoom)/2-n.x*S.zoom,y:(usableHeight-n.h*S.zoom)/2+25-n.y*S.zoom};applyCamera();revealSelectedNode();frameCanvasNodeControls();document.querySelector(`[data-node="${id}"]`)?.focus({preventScroll:true});save()}
function selectNode(id,edit=false){
 if(!nodeById(id))return;document.querySelector('.canvas-followup-menu')?.remove();canvasSelectedLink=null;S.selected=id;syncCanvasNavigatorSelection();
 if(!edit&&S.panel){S.panel=null;document.querySelector('.inspector')?.remove();}
 if(!edit&&S.panel!=='selection'){
 document.querySelectorAll('[data-node]').forEach(el=>el.classList.toggle('selected',el.dataset.node===id));
 document.querySelector('.selection-toolbar')?.remove();document.getElementById('viewport')?.insertAdjacentHTML('beforeend',selectionToolbar());drawEdges();refreshCanvasCreation();positionSelectionToolbar();save();return;
 }
 S.panel='selection';render();document.querySelector(`[data-node="${id}"]`)?.focus({preventScroll:true});save();
}
function zoomBy(factor,cx,cy){const v=document.getElementById('viewport');if(!v)return;const previous=S.zoom;const next=Math.max(Math.min(.01,previous),Math.min(1.6,previous*factor));cx??=v.clientWidth/2;cy??=v.clientHeight/2;S.pan={x:cx-(cx-S.pan.x)/previous*next,y:cy-(cy-S.pan.y)/previous*next};S.zoom=next;applyCamera();save()}
/** Cancel an interrupted gesture without committing a partial move to canvas history. */
function cancelCanvasDrag(){
 const state=drag;if(!state)return;drag=null;state.viewport.classList.remove('panning');
 if(state.project===S.project){
  if(state.type==='pan')S.pan={x:state.x,y:state.y};
  else{const node=nodeById(state.id),element=document.querySelector(`[data-node="${state.id}"]`);if(node){node.x=state.x;node.y=state.y;if(element){element.style.left=node.x+'px';element.style.top=node.y+'px';}}}
  applyCamera();save();
 }
 if(state.viewport.hasPointerCapture(state.pointerId))state.viewport.releasePointerCapture(state.pointerId);
}
function setupCanvas(){const vp=document.getElementById('viewport');if(!vp)return;vp.addEventListener('wheel',event=>{if(event.target.closest('.canvas-creation,.selection-toolbar'))return;event.preventDefault();if(event.ctrlKey||event.metaKey){const r=vp.getBoundingClientRect();zoomBy(Math.exp(-event.deltaY*.006),event.clientX-r.left,event.clientY-r.top)}else{S.pan.x-=event.deltaX;S.pan.y-=event.deltaY;applyCamera();save()}},{passive:false});vp.addEventListener('pointerdown',event=>{if(event.button!==0&&event.button!==1)return;if(event.target.closest('button,input,textarea,select,summary,.selection-toolbar,.canvas-creation,.canvas-link-panel,.canvas-link-hit,.floating-tools,.canvas-bottom,.storyboard-list'))return;const header=event.target.closest('[data-drag]');if(header&&S.mode!=='pan'&&!spaceDown){const n=nodeById(header.dataset.drag);selectNode(n.id);drag={type:'node',project:S.project,viewport:vp,pointerId:event.pointerId,id:n.id,startX:event.clientX,startY:event.clientY,x:n.x,y:n.y,changed:false};vp.setPointerCapture(event.pointerId)}else if(!event.target.closest('.node')||S.mode==='pan'||spaceDown||event.button===1){drag={type:'pan',project:S.project,viewport:vp,pointerId:event.pointerId,startX:event.clientX,startY:event.clientY,x:S.pan.x,y:S.pan.y,changed:false};vp.classList.add('panning');vp.setPointerCapture(event.pointerId)}});vp.addEventListener('pointermove',event=>{if(!drag||event.pointerId!==drag.pointerId)return;const dx=event.clientX-drag.startX,dy=event.clientY-drag.startY;drag.changed=Math.abs(dx)+Math.abs(dy)>3;if(drag.type==='node'){const n=nodeById(drag.id);n.x=drag.x+dx/S.zoom;n.y=drag.y+dy/S.zoom;if(S.referenceGridSnap){n.x=Math.round(n.x/20)*20;n.y=Math.round(n.y/20)*20;}const el=document.querySelector(`[data-node="${n.id}"]`);el.style.left=n.x+'px';el.style.top=n.y+'px';const groups=document.getElementById('script-groups');if(groups)groups.innerHTML=scriptCanvasGroups();drawEdges();syncCanvasRecovery();drawMinimap();positionSelectionToolbar()}else{S.pan={x:drag.x+dx,y:drag.y+dy};applyCamera()}});vp.addEventListener('pointerup',event=>{if(!drag||event.pointerId!==drag.pointerId)return;vp.classList.remove('panning');if(drag.type==='node'&&drag.changed){studioRecordCanvasHistory({id:drag.id,x:drag.x,y:drag.y});toast('节点位置已保存')}if(drag.changed||drag.type==='node')vp.dataset.dragged='yes';setTimeout(()=>delete vp.dataset.dragged,20);drag=null;save();if(vp.hasPointerCapture(event.pointerId))vp.releasePointerCapture(event.pointerId)});for(const name of ['pointercancel','lostpointercapture'])vp.addEventListener(name,event=>{if(drag?.pointerId===event.pointerId)cancelCanvasDrag()});document.getElementById('minimap').onclick=event=>{const r=event.currentTarget.getBoundingClientRect(),layout=minimapMapping();if(!layout)return;const x=layout.minX+(event.clientX-r.left-layout.offsetX)/layout.scale,y=layout.minY+(event.clientY-r.top-layout.offsetY)/layout.scale;S.pan={x:vp.clientWidth/2-x*S.zoom,y:vp.clientHeight/2-y*S.zoom};applyCamera();save()};setupTimelineDrag()}
function setupTimelineDrag(){let draggedClip;document.querySelectorAll('[data-clip]').forEach(el=>{el.addEventListener('dragstart',e=>{draggedClip=el.dataset.clip;e.dataTransfer.effectAllowed='move'});el.addEventListener('dragover',e=>e.preventDefault());el.addEventListener('drop',e=>{e.preventDefault();if(!draggedClip||draggedClip===el.dataset.clip)return;const from=S.clips.indexOf(draggedClip),to=S.clips.indexOf(el.dataset.clip);S.clips.splice(from,1);S.clips.splice(to,0,draggedClip);render();toast('镜头顺序已更新，原成片保持不变')})})}
let modalOpener=null;
function showDialog(title,body,footer='',wide=false){const opener=document.activeElement;closeDialog();modalOpener=opener;currentModal=title;const root=document.getElementById('modal-root');root.innerHTML=`<div class="overlay" id="overlay"><section class="dialog ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header class="dialog-header"><h2>${esc(title)}</h2>${iconBtn('关闭弹窗','close-modal','close')}</header><div class="dialog-body">${body}</div>${footer?`<footer class="dialog-footer">${footer}</footer>`:''}</section></div>`;root.querySelector('button')?.focus();root.querySelector('#overlay').addEventListener('click',e=>{if(e.target.id==='overlay')closeDialog()});return root}
function closeDialog(){const navigatorReturn=document.querySelector('.dialog[data-candidate-review]')&&document.getElementById('viewport')?.clientWidth<=720?document.querySelector('.canvas-navigator [data-action="canvas-outline"]'):null;clearInterval(previewTimer);previewTimer=null;previewPlaying=false;document.getElementById('modal-root').innerHTML='';currentModal=null;if(navigatorReturn)navigatorReturn.focus({preventScroll:true});else if(modalOpener?.isConnected)modalOpener.focus({preventScroll:true});modalOpener=null}
function approval(stage){const video=stage==='video';showDialog(video?'确认视频制作':'确认分镜预览',`<p>${video?'画面和人物已确认，现在把已采用的分镜制作成视频。只会处理本集需要制作的镜头。':'先用低成本预览确认人物与构图。通过后，你再决定是否制作视频。'}</p><div class="approval-items">${(video?[['film',S.clips.length+' 个镜头视频','共 '+projectDuration()+' 秒'],['mic','对白与环境声音','统一音色'],['layers','成片初剪','字幕同步']]:[['user','角色与场景参考','复用已采用素材'],['image',S.clips.length+' 张分镜关键帧','保留每张候选'],['film','动态分镜预览','审阅后再做视频']]).map(([i,t,d])=>`<div class="approval-item">${I(i)}${t}<span>${d}</span></div>`).join('')}</div><div class="cost-box"><small>本阶段费用估算<br><span style="display:block;margin-top:5px;color:var(--muted)">本集上限 ¥30 · 演示估算</span></small><strong><small>预计</small>¥${video?'15.40':'3.20'}</strong></div><label class="approval-check"><input type="checkbox" checked>超出预算或遇到不确定结果时暂停，交给我确认</label>`,`<span class="note">样式演示，不调用 API 或扣费</span>${btn('再看看','close-modal','outline')}${btn(video?'确认并制作':'确认预览方案',video?'run-video':'run-preview','primary','check')}`)}
function runSimulation(stage){
 closeDialog();const video=stage==='video';if(video&&S.clips.some(id=>nodeById(id)?.referenceOnly)){showPendingClipExport();return}S.approved=true;
 if(video){S.videoReady=true;S.nodes.filter(n=>n.kind==='shot'||n.kind==='final').forEach(n=>n.status='已完成');S.spent=18.6;S.timeline=true;S.panel='director';}
 else S.nodes.filter(n=>n.kind==='shot').forEach(n=>n.status='已采用');
 S.history.push({type:'demo-stage',stage,createdAt:new Date().toISOString()});render();
 toast(video?'已展示视频就绪状态，可继续预览与剪辑':'预览方案已确认，视频制作仍需单独确认');
}
function preview(){
 const clips=projectClips(),duration=projectDuration();if(!clips.length){toast('先添加需要预览的镜头');return}
 previewTime=0;
 showDialog('分镜预览 · '+S.project,`<div class="preview-screen"><div class="preview-picture ${clips[0].referenceOnly?'pending-media':'still frame'+clips[0].frame}" id="preview-picture">${clips[0].referenceOnly?esc(clips[0].title)+' · 待制作':''}</div><span class="preview-corner">STUDIO · 动态分镜示意</span><div class="subtitle" id="preview-subtitle">${clips[0].referenceOnly?'':esc(clips[0].dialogue)}</div></div><div class="preview-controls">${iconBtn('播放分镜预览','toggle-play','play')}<span class="mono" id="preview-timer">00:00</span><input id="preview-scrub" type="range" min="0" max="${duration}" step=".1" value="0" aria-label="预览进度"><span class="mono">${timeLabel(duration)}</span></div><p class="preview-note">已有镜头使用当前采用结果，未制作镜头以占位显示。此处为动态分镜示意。</p>`,`${btn('回到画布','close-modal','outline')}${btn('继续剪辑','preview-edit','primary','film')}`,true);
 document.getElementById('preview-scrub').oninput=e=>{previewTime=Number(e.target.value);updatePreview()};
}
function updatePreview(){
 const clips=projectClips();if(!clips.length)return;let t=previewTime,index=0;
 for(let i=0;i<clips.length;i++){if(t<clips[i].seconds){index=i;break}t-=clips[i].seconds;index=Math.min(i+1,clips.length-1)}
 const n=clips[index],picture=document.getElementById('preview-picture');if(!picture)return;
 picture.className=`preview-picture ${n.referenceOnly?'pending-media':'still frame'+n.frame} ${previewPlaying?'moving':''}`;picture.textContent=n.referenceOnly?n.title+' · 待制作':'';
 document.getElementById('preview-subtitle').textContent=n.referenceOnly?'':n.dialogue;
 document.getElementById('preview-timer').textContent=timeLabel(previewTime);
 document.getElementById('preview-scrub').value=previewTime;
}
function togglePreview(){
 previewPlaying=!previewPlaying;const b=document.querySelector('[data-action="toggle-play"]');b.innerHTML=I(previewPlaying?'pause':'play');b.setAttribute('aria-label',previewPlaying?'暂停分镜预览':'播放分镜预览');clearInterval(previewTimer);
 if(previewPlaying){previewTimer=setInterval(()=>{previewTime+=.1;if(previewTime>=projectDuration()){previewTime=0;previewPlaying=false;clearInterval(previewTimer);b.innerHTML=I('play');b.setAttribute('aria-label','播放分镜预览')}updatePreview()},100)}updatePreview();
}
function library(type){if(type==='assets'){openStudioAssetLibrary();return}const isAssets=type==='assets',isExperts=type==='experts';const title=isAssets?'项目资产库':isExperts?'你的创作专家':'从一个成熟的创作方案开始';const items=isAssets?[['林晚','角色 · 奶白风衣',1],['守站人','角色 · 深蓝工作服',2],['旧站台','场景 · 雨夜',0],['雨巷','场景 · 路灯暖光',4],['旧灯','道具 · 故事关键物',3],['街口','场景 · 黎明',5]]:isExperts?[['编剧','故事结构与对白',1],['导演','表演、节奏与画面',3],['分镜师','镜头表达与连续性',0],['美术指导','人物与场景一致性',2],['剪辑师','节奏、声音与成片',4],['制作统筹','预算与任务安排',5]]:[['温暖剧情短片','30 秒 · 2 角色 · 4 镜头',3],['城市雨夜','60 秒 · 情绪叙事',0],['人物独白','45 秒 · 低成本旁白',1],['小说轻漫剧','60 秒 · 旁白与轻动态',2],['生活小故事','30 秒 · 单场景短片',4],['风格参考复刻','选定参考，只借鉴表现',5]];showDialog(title,`<p>${isAssets?'同一资产可以被多个镜头引用。修改时提示影响范围，历史采用结果始终保留。':isExperts?'复用 CrewON 专家库，导演助手负责统筹。你随时可以查看分工。':'模板包含故事结构、镜头节奏和制作策略。选一个开始，再改成自己的故事。'}</p><div class="dialog-grid">${items.map(([n,d,f])=>`<article class="library-card"><div class="still frame${f}"></div><div><h3>${n}</h3><p>${d}</p>${btn(isAssets?'引用到画布':isExperts?'加入创作团队':'使用此模板',(isAssets?'import-asset:':isExperts?'add-expert:':'template:')+n,'outline',isAssets?'plus':isExperts?'people':'arrow')}</div></article>`).join('')}</div>`,`${btn('完成','close-modal','outline')}`,true)}
