function addNode(kind,title,reference=null,options={}){const v=document.getElementById('viewport');if(!v){openProject();setTimeout(()=>addNode(kind,title,reference),40);return}const before=referenceCaptureNodeGraph(S),id=studioScriptId('node');const n={id,kind,label:{text:'文字',image:'图片',video:'视频',story:'剧本片段',character:'角色',scene:'场景',shot:'镜头',voice:'声音',note:'灵感便签'}[kind],title:title||{text:'新的文字',image:'新的图片',video:'新的视频',story:'新的故事片段',character:'新的角色',scene:'新的场景',shot:'新的镜头',voice:'温暖的旁白',note:'待发展的想法'}[kind],description:'选中节点，和导演助手一起完善这份创作。',x:(v.clientWidth/2-S.pan.x)/S.zoom-130,y:(v.clientHeight/2-S.pan.y)/S.zoom-150,w:options.width??(['video','voice','audio'].includes(kind)?380:268),h:options.height??(kind==='video'?214:['voice','audio'].includes(kind)?220:300),...(options.derivedOperation?{derivedOperation:options.derivedOperation}:{}),...(options.creationPreferences?{creationPreferences:structuredClone(options.creationPreferences)}:{}),status:'草稿',frame:kind==='character'?2:4,seconds:kind==='video'?5:6,dialogue:'',prompt:''};Object.assign(n,studioNewContentPosition(n.w,n.h));if(studioCandidateKinds.has(kind)){n.referenceOnly=true;n.adoptedCandidateId=null;n.candidates=[]}S.nodes.push(n);if(reference){const result=studioApplyAssetReferences(n,[reference],false);if(!result.ok){S.nodes.pop();toast(result.error);return null;}}studioRecordCanvasHistory(referenceNodeGraphPatch(before,referenceCaptureNodeGraph(S)));canvasSelectedLink=null;S.selected=id;S.panel=reference||['video','voice','audio'].includes(kind)?null:'selection';render();revealSelectedNode();if(['video','voice','audio'].includes(kind))frameCanvasNodeControls();save();toast(reference?'已新建'+n.label+'草稿并锁定参考版本':'已添加 '+n.label+'，可拖动调整位置');return n;}
