function rememberProject(){
 if(!S.project||!Array.isArray(S.nodes))return;
 S.projectDrafts[S.project]=Object.fromEntries(['project','projectKind','referenceProjectEdit','referenceCreationSpec','referenceSourceScript','referenceCanvasViews','referenceGroupNames','referenceGroups','referenceTagCatalog','referenceBoard','nodes','edges','clips','history','versions','approved','videoReady','revision','pan','zoom','layoutBase','nodeDrafts','spent','canvasUndo','canvasRedo'].map(k=>[k,structuredClone(S[k])]));
}
function loadStudioExample(key, fresh=false, brief=''){
 const recipe=makeStudioExample(key,brief);
 const saved=!fresh&&S.projectDrafts[recipe.project];
 Object.assign(S,saved||recipe);S.referenceProjectEdit=structuredClone(saved?.referenceProjectEdit??null);S.referenceCreationSpec=structuredClone(saved?.referenceCreationSpec??null);S.referenceSourceScript=structuredClone(saved?.referenceSourceScript??null);S.referenceCanvasViews=structuredClone(saved?.referenceCanvasViews??[]);S.referenceGroupNames=structuredClone(saved?.referenceGroupNames??{});S.referenceGroups=structuredClone(saved?.referenceGroups??null);S.referenceTagCatalog=structuredClone(saved?.referenceTagCatalog??null);S.referenceBoard=structuredClone(saved?.referenceBoard??null);if(saved){S.nodeDrafts=structuredClone(saved.nodeDrafts||{});S.canvasRedo=structuredClone(saved.canvasRedo||[]);S.canvasUndo=structuredClone(saved.canvasUndo||saved.history?.filter(h=>(h.id&&Number.isFinite(h.x)&&Number.isFinite(h.y))||h.type==='layout')||[]);}
 if(!saved){S.canvasUndo=[];S.canvasRedo=[];S.nodeDrafts={};S.spent=0;S.history=brief?[{type:'brief',text:brief,createdAt:new Date().toISOString()}]:[];S.versions={};S.approved=false;S.videoReady=false;S.revision=1;S.layoutBase=S.nodes.map(n=>({id:n.id,x:n.x,y:n.y}));}
 if(fresh){const base=S.project;do{S.projectSequence=(S.projectSequence||0)+1;S.project=base+' · 草稿 '+S.projectSequence;}while(S.projectDrafts[S.project]);}
 S.screen='canvas';S.goal=key;S.view='canvas';S.scene='all';S.timeline=false;S.selected=null;S.panel=null;S.toolCategory=0;location.hash='canvas';render();if(!saved)fitCanvas(key==='previs');
}
