function genericDirector(){
 const label=({previs:'镜头预演',interactive:'互动故事',blank:'自由创作'})[S.projectKind]||'作品创作';
 const steps=S.projectKind==='previs'?['确认场景与人物动作','比较机位与构图','审阅预演后再制作']:S.projectKind==='interactive'?['确认主线与人物','整理选择与结局','试走故事，再制作素材']:['整理创作目标','准备素材与制作方案','预览后再决定制作'];
 return `<div class="director-header"><div class="director-avatar">${I('spark')}</div><div><h3>创作助手</h3><p>复用 CrewON 专家与工具</p></div></div><p class="director-message">${S.projectKind==='blank'?'先把素材放进来。你可以从任意一份内容开始，逐步整理自己的创作方向。':`这是一份${label}方案。先确认表达与参考，再选择需要处理的内容。`}</p><div class="plan-card"><div class="plan-card-head">${I('layers')}这次怎么做<span class="pill">${label}</span></div><section>${steps.map((step,i)=>`<div class="plan-line ${i===0?'done':i===1?'active':''}"><span class="plan-number">${i===0?I('check'):i+1}</span><span>${step}</span><span class="state">${i===0?'已准备':S.approved?'可继续':'待确认'}</span></div>`).join('')}<div class="plan-cost"><span>用量与费用</span><strong>连接服务后估算</strong></div></section>${btn(S.projectKind==='blank'?'添加第一份素材':'审阅创作方案',S.projectKind==='blank'?'add-node':'review-project','primary','arrow')}<p class="plan-disclaimer">交互演示 · 确认前不执行生成</p></div><p class="director-note">点击画布中的内容，查看适合它的创作工具。原素材和采用版本会分别保留。</p>${btn('查看全部创作工具','all-tools','outline','layers')}`;
}
function toolDirectory(category){
 const kind=category||mediaKind(nodeById(S.selected));
 const tabs=[['image','图片','image'],['video','视频','film'],['audio','声音','mic'],['text','文字','file']];
 showDialog('创作工具',`<p>先选择画布内容，再使用相关工具。这里展示使用方式，所有结果均为示意。</p><div class="home-targets" role="tablist" aria-label="工具类型">${tabs.map(([k,l,i])=>`<button role="tab" aria-selected="${kind===k}" class="target-tab ${kind===k?'active':''}" data-action="tool-directory:${k}">${I(i)}${l}</button>`).join('')}</div><div class="tool-directory">${studioTools[kind].map(group=>`<section class="tool-category"><h3>${group.name}</h3><div class="quick-tool-grid">${group.items.map(t=>`<button class="quick-tool" data-action="tool:${t}">${I(kind==='image'?'image':kind==='video'?'film':kind==='audio'?'mic':'file')}<span>${t}</span>${I('chev')}</button>`).join('')}</div></section>`).join('')}</div>`,btn('返回创作','close-modal','outline'),true);
}
let pendingStudioTool=null;
function showStudioTool(name){
 const node=nodeById(S.selected);
 if(['图转 3D','图转空间','画板与标注','对白与音乐混合'].includes(name)){
  showDialog(name,`<p>这一项已纳入专业空间设计，当前 Demo 展示其入口与使用场景。</p><div class="approval-items"><div class="approval-item">${I('layers')}沿用选中内容与引用<span>保留项目上下文</span></div><div class="approval-item">${I('edit')}进入专用编辑空间<span>后续展开设计</span></div></div><p>模型目录存在相关能力，并不表示可交互编辑器已完成。本轮不展示虚假的 3D、绘图或混音结果。</p>`,btn('回到画布','close-modal','outline'));return;
 }
 if(!node){
  const group=Object.entries(studioTools).find(([,groups])=>groups.some(g=>g.items.includes(name)));
  const goal=group?.[0]==='text'?'blank':group?.[0]||'image';
  showDialog(name,`<p>先在画布选择一份内容。已有素材可继续编辑，也可以从示例项目了解这项工具的用法。</p>`,`${btn('返回','close-modal','outline')}${btn('打开相关示例','tool-example:'+goal,'primary','arrow')}`);return;
 }
 pendingStudioTool={name,nodeId:node.id};
 const imageGrid=name.includes('宫格');
 showDialog(name,`<div class="tool-source">${I(kindIcon[node.kind]||'file')}<span>基于「${esc(node.title)}」</span><span class="pill">保留原内容</span></div><label class="field">${mediaKind(node)==='audio'?'声音要求':'想怎样调整'}<textarea id="tool-instruction" placeholder="补充你想保留和改变的部分">${esc(imageGrid?'保持人物、场景与光线一致，比较不同构图与表现。':node.prompt||node.description||'')}</textarea></label><div class="field-grid"><label class="field">候选数量<select id="tool-count"><option value="1">1 个候选</option><option value="2">2 个候选</option></select></label><label class="field">结果比例<select id="tool-ratio"><option>沿用来源</option><option>16:9 横版</option><option>9:16 竖版</option></select></label></div><p>${imageGrid?'图片宫格用于比较机位与情节构图，不会生成连续视频。':'本次调整只针对所选内容，其他结果继续保留。'}</p><div class="cost-box"><small>正式执行前核对模型、用量与费用</small><strong class="cost-label">本轮仅演示</strong></div>`,`${btn('取消','close-modal','outline')}${btn('演示新增候选','confirm-tool-demo','primary','plus')}`);
}
function confirmStudioTool(){
 if(!pendingStudioTool)return;const source=nodeById(pendingStudioTool.nodeId);if(!source)return;
 const instruction=document.getElementById('tool-instruction')?.value||source.prompt||'';
 const count=Number(document.getElementById('tool-count')?.value)||1;
 const ratio=document.getElementById('tool-ratio')?.value||'沿用来源';
 const toolType=Object.entries(studioTools).find(([,groups])=>groups.some(g=>g.items.includes(pendingStudioTool.name)))?.[0]||mediaKind(source);
 const outputKind={image:'image',video:'video',audio:'voice',text:'text'}[toolType];
 const sourceCopy=structuredClone(source);delete sourceCopy.candidates;delete sourceCopy.adoptedCandidateId;
 const created=Array.from({length:count},(_,i)=>({...structuredClone(sourceCopy),kind:outputKind,label:{image:'图片候选',video:'视频候选',voice:'声音候选',text:'文字候选'}[outputKind],id:'candidate-'+Date.now()+'-'+i,title:pendingStudioTool.name+' · 候选'+(count>1?' '+(i+1):''),x:source.x+source.w+80,y:source.y+55+i*360,status:'示例候选',prompt:instruction,ratio,frame:(source.frame+i+1)%6}));
 for(const next of created){S.nodes.push(next);S.edges.push([source.id,next.id]);S.history.push({type:'tool-demo',name:pendingStudioTool.name,sourceId:source.id,targetId:next.id,ratio});}
 closeDialog();S.view='canvas';focusNode(created[0].id);toast('示例候选已添加，原内容保留');pendingStudioTool=null;
}
function reviewStudioProject(){
 if(S.projectKind==='drama'){approval(S.approved?'video':'preview');return}
 const n=primaryStudioNode();
 showDialog(S.projectKind==='previs'?'审阅预演方案':S.projectKind==='interactive'?'审阅故事结构':'审阅创作方案',`<p>确认这次处理的内容和保留范围，再决定是否执行。</p><div class="approval-items"><div class="approval-item">${I('file')}创作目标<span>${({previs:'镜头预演',interactive:'互动故事'})[S.projectKind]||'作品创作'}</span></div><div class="approval-item">${I(kindIcon[n?.kind]||'image')}当前内容<span>${esc(n?.title||'尚未选择')}</span></div><div class="approval-item">${I('layers')}结果采用方式<span>新增候选，保留来源</span></div></div><div class="cost-box"><small>真实执行需连接 API 并估算用量</small><strong class="cost-label">交互演示</strong></div>`,`<span class="note">不调用 API，不计费</span>${btn('继续调整','close-modal','outline')}${btn('确认示例方案','confirm-project-demo','primary','check')}`);
}
function finishStudioProject(){
 closeDialog();S.approved=true;const n=primaryStudioNode();if(n){n.status='示例就绪';focusNode(n.id)}else render();toast('示例方案已确认，真实生成尚未启动');
}
function previewStudioContent(){
 const n=primaryStudioNode();if(!n)return;
 const kind=mediaKind(n);
 showDialog(kind==='audio'?'声音稿预览':kind==='text'?'内容预览':'画面预览',`${['image','video'].includes(kind)?`<div class="preview-screen"><div class="preview-picture still frame${n.frame}"></div><span class="preview-corner">${kind==='video'?'视频画面示意':'摄影素材示意'}</span></div>`:`<div class="content-preview">${I(kind==='audio'?'mic':'file')}<p>${esc(n.dialogue||n.text||n.prompt||n.description)}</p></div>`}<p class="preview-note">${kind==='video'?'当前展示视频画面与审阅布局，不是真实生成视频。':kind==='audio'?'当前仅审阅声音稿，不合成或播放真实配音。':'本轮使用已有示意内容，不代表真实生成结果。'}</p>`,`${btn('回到画布','close-modal','outline')}${btn('查看内容属性','preview-properties:'+n.id,'primary','sliders')}`,true);
}
function deliverStudioContent(){
 showDialog('交付这份作品',`<p>采用的结果、来源与制作记录保留在同一个项目中。此 Demo 可下载制作方案，用于评审后续执行与交付设计。</p><div class="approval-items"><div class="approval-item">${I('folder')}项目<span>${esc(S.project)}</span></div><div class="approval-item">${I('layers')}内容与关系<span>${S.nodes.length} 项内容</span></div><div class="approval-item">${I('history')}历史采用<span>保留原版本</span></div></div><p>本轮下载 JSON 方案，不导出图片、音频或视频媒体文件。</p>`,`${btn('返回','close-modal','outline')}${btn('下载制作方案','download-plan','primary','download')}`);
}
document.addEventListener('click',e=>{
 const goal=e.target.closest('[data-goal]');if(!goal)return;
 S.drafts.shared=document.getElementById('idea-input')?.value||S.drafts.shared||'';
 S.goal=goal.dataset.goal;render();document.querySelector(`[data-goal="${S.goal}"]`)?.focus();
});

function workPreferences(){
 const prefs=S.workPreferences||{preview:true,reuse:true,confirm:true};
 showDialog('制作偏好',`<p>先把方向确认好，再把预算花在采用的结果上。</p><label class="preference-row"><input type="checkbox" id="pref-preview" ${prefs.preview?'checked':''}><span><strong>先看低成本预览</strong><small>关键帧与构图通过后，再制作视频</small></span></label><label class="preference-row"><input type="checkbox" id="pref-reuse" ${prefs.reuse?'checked':''}><span><strong>优先复用已有素材</strong><small>沿用已采用的角色、场景和声音</small></span></label><label class="preference-row"><input type="checkbox" id="pref-confirm" ${prefs.confirm?'checked':''}><span><strong>执行前确认用量与费用</strong><small>状态不明确时先查询原任务，避免重复提交</small></span></label>`,`<span class="note">原型偏好，仅保存在此浏览器</span>${btn('保存偏好','save-work-preferences','primary')}`);
}
function importStartingPoint(kind){
 const script=kind==='script';
 showDialog(script?'从已有剧本开始':'从参考作品开始',`<p>${script?'带上已有故事，先确认制作范围和希望保留的内容。':'说明希望借鉴的表达、节奏或构图，先审阅改编方向。'}</p><label class="field">${script?'剧本或制作要求':'参考内容与调整目标'}<textarea id="starting-text" placeholder="${script?'粘贴剧本片段，或说明想制作哪一部分…':'例如：沿用参考片的节奏，重新设计人物与故事…'}"></textarea></label><label class="asset-import"><input id="starting-file" type="file" accept="${script?'.txt,.md,.doc,.docx':'image/*,video/*'}"><span>此 Demo 仅记录文件名，不上传或解析文件</span></label>`,`${btn('取消','close-modal','outline')}${btn('继续规划','plan-import:'+kind,'primary','arrow')}`);
}
function prepareWorkPlan(kind){
 const spec={drama:{label:'剧情短片',steps:['梳理故事与角色','拆分场景和镜头','先做分镜预览','确认后制作与剪辑'],inputs:'目标、剧本或参考素材',result:'可继续编辑的短片项目'},previs:{label:'镜头预演',steps:['明确场景与人物动作','整理空间和机位','比较构图与运动意图','确认后制作镜头'],inputs:'场景、人物动作与镜头目标',result:'机位草图、构图参考与预演方案'},interactive:{label:'互动故事',steps:['明确人物与故事主线','设置关键选择','检查路径与结局','再制作画面与声音'],inputs:'主角、故事目标与关键选择',result:'可编辑的故事结构与分支试走'}}[kind]||{label:'自由创作',steps:['整理目标','放入素材','逐步继续'],inputs:'已有内容',result:'项目画布'};
 const brief=S.drafts.shared||'体验示例：雨夜车站里，一盏灯改变了两个陌生人的相遇。';
 showDialog('先确认这份制作方案',`<div class="plan-source"><span class="pill">${spec.label}</span><span>示例方案 · 用于评审交互</span></div><div class="plan-recipes" role="group" aria-label="切换制作方案">${[['drama','剧情短片'],['previs','镜头预演'],['interactive','互动故事'],['blank','自由创作']].map(([key,label])=>`<button class="${key===kind?'active':''}" aria-pressed="${key===kind}" data-action="switch-work-plan:${key}">${label}</button>`).join('')}</div><h3 class="plan-goal">${esc(brief)}</h3><div class="work-plan-steps">${spec.steps.map((step,i)=>`<div><span>${i+1}</span><p>${step}</p></div>`).join('')}</div><div class="plan-facts"><div><span>需要什么</span><strong>${spec.inputs}</strong></div><div><span>得到什么</span><strong>${spec.result}</strong></div><div><span>先做什么</span><strong>低成本预览与内容核对</strong></div></div><p>这轮进入预设示例画布，不启动 Agent 或生成 API。正式产品由创作助手按目标推荐方案，必要时再补少量关键信息。</p>`,`${btn('继续调整','close-modal','outline')}${btn('进入示例画布','enter-work-plan:'+kind,'primary','arrow')}`,true);
}
function enterWorkPlan(kind){
 closeDialog();rememberProject();loadStudioExample(kind,true,S.drafts.shared||'');
}
function cameraNodeBody(n){
 return `<div class="previs-stage"><svg viewBox="0 0 280 156" role="img" aria-label="站台人物与机位的平面草图"><path class="stage-floor" d="M18 25H260V130H18Z"/><path class="stage-track" d="M18 42H260M18 113H260"/><circle cx="99" cy="73" r="9"/><circle cx="179" cy="89" r="9"/><path class="camera-path" d="M38 105Q96 122 148 104T239 73"/><path d="m228 69 12 4-8 9"/><text x="77" y="58">旅人</text><text x="158" y="116">守站人</text><rect x="29" y="96" width="15" height="11" rx="2"/></svg><span>平面机位示意 · 非 3D 渲染</span></div><div class="node-content"><h3>${esc(n.title)}</h3><p>${esc(n.prompt)}</p></div>`;
}
function choiceNodeBody(n){return `<div class="node-content node-text"><h3>${esc(n.title)}</h3><p>${esc(n.text)}</p><div class="story-options">${n.options.map((o,i)=>`<button data-action="story-focus:${o.target}"><span>${String.fromCharCode(65+i)}</span>${esc(o.label)}${I('arrow')}</button>`).join('')}</div></div>`;}
function choiceProperties(n){
 const endings=S.nodes.filter(x=>x.kind==='ending');
 return `<h2 class="inspector-title">${esc(n.title)}</h2><p class="inspector-sub">选择点 · 两条可编辑路径</p><label class="field">选择前的情节<textarea id="choice-text">${esc(n.text)}</textarea></label>${n.options.map((o,i)=>`<div class="choice-editor"><label class="field">选项 ${String.fromCharCode(65+i)}<input id="choice-label-${i}" value="${esc(o.label)}"></label><label class="field">进入情节<select id="choice-target-${i}">${endings.map(end=>`<option value="${end.id}" ${o.target===end.id?'selected':''}>${esc(end.title)}</option>`).join('')}</select></label></div>`).join('')}<div class="inspector-buttons">${btn('保存故事结构','save-choice','outline','check')}${btn('试走故事','story-play','primary','play')}</div><p class="inspector-feedback">修改选择与连接后，可以先试走路径；不必重新生成所有画面。</p>`;
}
function saveStoryChoice(){
 const n=nodeById(S.selected);if(n?.kind!=='choice')return;
 n.text=document.getElementById('choice-text').value;
 n.options=n.options.map((o,i)=>({label:document.getElementById('choice-label-'+i).value||o.label,target:document.getElementById('choice-target-'+i).value}));
 S.edges=S.edges.filter(([from])=>from!==n.id).concat(n.options.map(o=>[n.id,o.target]));render();toast('故事结构已保存');
}
function playStory(target){
 const choice=S.nodes.find(n=>n.kind==='choice');if(!choice)return;
 const ending=target&&nodeById(target);
 showDialog(ending?'故事试走 · '+ending.label:'故事试走',`<div class="preview-screen"><div class="preview-picture still frame${ending?ending.frame:0}"></div><span class="preview-corner">静态故事示意</span></div><h3 class="story-preview-title">${ending?esc(ending.title):esc(choice.title)}</h3><p>${ending?esc(ending.description):esc(choice.text)}</p>${ending?'':`<div class="story-play-options">${choice.options.map(o=>btn(esc(o.label),'story-play:'+o.target,'outline','arrow')).join('')}</div>`}<p class="preview-note">此处试走叙事路径，不播放实际生成视频，也不表示互动作品已经发布。</p>`,`${btn(ending?'重新选择':'回到画布',ending?'story-play':'close-modal','outline')}${ending?btn('返回故事结构','close-modal','primary'):''}`,true);
}

let spaceDown=false;
document.addEventListener('keydown',e=>{if(e.defaultPrevented)return;if(e.key==='Escape'&&!currentModal&&canvasActiveTool&&!document.querySelector('.canvas-tool-menu[open],.creation-settings[open]')){handleCanvasNodeToolAction('canvas-tool-close');e.preventDefault();return}if(e.key==='Escape'&&document.querySelector('.canvas-tool-menu[open],.creation-settings[open]')){const menu=document.querySelector('.canvas-tool-menu[open],.creation-settings[open]');menu.open=false;menu.querySelector('summary').focus();e.preventDefault();return}if(e.key==='Escape'&&document.querySelector('.node-more[open]')){const menu=document.querySelector('.node-more[open]');menu.open=false;menu.querySelector('summary').focus();e.preventDefault();return}if(e.key==='Escape'&&document.querySelector('.add-popover')){document.querySelector('.add-popover').remove();document.querySelector('[data-action="add-node"]')?.focus();e.preventDefault();return}if(e.target.matches('[data-goal]')&&['ArrowLeft','ArrowRight'].includes(e.key)){const ids=Object.keys(studioGoals),at=ids.indexOf(S.goal);S.goal=ids[(at+(e.key==='ArrowRight'?1:ids.length-1))%ids.length];render();document.querySelector(`[data-goal="${S.goal}"]`)?.focus();e.preventDefault();return}if(currentModal&&e.key==='Tab'){const controls=[...document.querySelectorAll('.dialog button,.dialog input,.dialog select,.dialog textarea')].filter(el=>!el.disabled);const first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){last?.focus();e.preventDefault()}else if(!e.shiftKey&&document.activeElement===last){first?.focus();e.preventDefault()}return}if(currentModal){if(e.key==='Escape'){closeDialog();e.preventDefault()}return}if(e.key==='Enter'&&e.target.matches('[data-node]')){selectNode(e.target.dataset.node);if(canvasCreationNode())document.getElementById('canvas-creation-prompt')?.focus({preventScroll:true});else handleAction('edit-node:'+e.target.dataset.node);e.preventDefault();return}const editing=/INPUT|TEXTAREA|SELECT/.test(e.target.tagName);if(!editing&&!currentModal&&['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)&&e.target.matches('[data-node]')){const n=nodeById(e.target.dataset.node);if(n){const step=e.shiftKey?40:10;studioRecordCanvasHistory({id:n.id,x:n.x,y:n.y});n.x+=(e.key==='ArrowRight'?step:e.key==='ArrowLeft'?-step:0);n.y+=(e.key==='ArrowDown'?step:e.key==='ArrowUp'?-step:0);e.target.style.left=n.x+'px';e.target.style.top=n.y+'px';drawEdges();drawMinimap();positionSelectionToolbar();save();e.preventDefault();return}}if(e.key==='Escape'){if(currentModal)closeDialog();else if(connecting){connecting=null;render();toast('已取消连线')}else if(S.panel){S.panel=null;render()}else if(S.selected){S.selected=null;render()}return}if(editing)return;if(e.code==='Space'&&S.screen==='canvas'&&e.target.closest('#viewport')&&!e.target.closest('button,a,[role="button"],[role="menuitem"],[role="tab"]')){spaceDown=true;e.preventDefault()}if(e.key.toLowerCase()==='f'&&S.screen==='canvas'){fitCanvas();e.preventDefault()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){handleAction(e.shiftKey?'redo':'undo');e.preventDefault()}if((e.ctrlKey||e.metaKey)&&e.key==='s'){persist();toast('此浏览器中的设计草稿已保存');e.preventDefault()}});
document.addEventListener('keyup',e=>{if(e.code==='Space')spaceDown=false});
document.addEventListener('input',e=>{if(e.target.id==='idea-input'){S.drafts.shared=e.target.value;save()}const draftKey=({'node-prompt':'prompt','node-dialogue':'dialogue','node-duration':'seconds','node-motion':'motion'})[e.target.id];if(draftKey&&S.selected){const n=nodeById(S.selected);if(n){const draft=studioEffectiveNodeDraft(n,{...S.nodeDrafts[S.selected],[draftKey]:e.target.value});if(Object.keys(draft).length)S.nodeDrafts[S.selected]=draft;else delete S.nodeDrafts[S.selected];save()}}if(e.target.id==='project-search'){const term=e.target.value.toLowerCase();document.querySelectorAll('.project-card,.draft-list button').forEach(c=>c.classList.toggle('hidden',!c.textContent.toLowerCase().includes(term)));const drafts=document.querySelector('.recent-drafts');if(drafts&&term)drafts.open=true}});
document.addEventListener('submit',event=>{
 if(event.target.id!=='director-form')return;event.preventDefault();
 const field=event.target.querySelector('textarea'),previousHistory=[...S.history],previousDraft=referenceAssistantDraft(S);
 if(!referenceCommitAssistantRequest(S,field.value,new Date().toISOString()))return;
 try{persist();}catch(error){S.history=previousHistory;referenceSetAssistantDraft(S,previousDraft);toast('请求未保存，请检查浏览器存储空间后重试');return;}
 render();const pane=document.querySelector('.ref-assistant-panel .inspector-content');if(pane)pane.scrollTop=pane.scrollHeight;document.querySelector('#director-form textarea')?.focus({preventScroll:true});
});
document.addEventListener('click',e=>{const action=e.target.closest('[data-action]');if(action){handleAction(action.dataset.action);return}const intake=e.target.closest('[data-intake]');if(intake){S.drafts.shared=document.getElementById('idea-input')?.value||S.drafts.shared||'';S.intake=intake.dataset.intake;render();return}const prompt=e.target.closest('[data-prompt]');if(prompt){S.drafts.shared=prompt.dataset.prompt;save();document.getElementById('idea-input').value=prompt.dataset.prompt;document.getElementById('idea-input').focus();return}const project=e.target.closest('[data-project]');if(project){openProject(project.dataset.project);return}const template=e.target.closest('[data-template]');if(template){handleAction('template:'+template.dataset.template);return}const focus=e.target.closest('[data-focus]');if(focus){focusNode(focus.dataset.focus);return}const selected=e.target.closest('[data-select]');if(selected){selectNode(selected.dataset.select);return}const view=e.target.closest('[data-view]');if(view){S.view=view.dataset.view;render();return}const out=e.target.closest('[data-port-out]');if(out){connecting=out.dataset.portOut;document.querySelectorAll('.port').forEach(p=>p.classList.remove('connecting'));out.classList.add('connecting');toast('选择左侧连接点，为下一次制作添加参考');return}const inn=e.target.closest('[data-port-in]');if(inn&&connecting){studioFinishCanvasConnection(connecting,inn.dataset.portIn);return}const node=e.target.closest('[data-node]');if(node&&!document.getElementById('viewport')?.dataset.dragged&&!drag){selectNode(node.dataset.node);return}const add=e.target.closest('[data-add]');if(add){addNode(add.dataset.add);return}const move=e.target.closest('[data-moveclip]');if(move){const from=S.clips.indexOf(move.dataset.moveclip),to=Math.max(0,Math.min(S.clips.length-1,from+Number(move.dataset.direction)));[S.clips[from],S.clips[to]]=[S.clips[to],S.clips[from]];render();toast('时间线顺序已调整');return}const clip=e.target.closest('[data-clip]');if(clip){selectNode(clip.dataset.clip);return}if(!e.target.closest('.floating-tools'))document.querySelector('.add-popover')?.remove()});
function handleAction(action){if(handleCanvasLinkAction(action)||handleCanvasNavigatorAction(action)||handleCanvasCreationAction(action)||handleStudioAssetAction(action)||handleScriptAction(action))return;const [key,...args]=action.split(':');const arg=args.join(':');switch(key){case'canvas-outline':S.outlineOpen=!S.outlineOpen;render();if(S.outlineOpen&&document.getElementById('viewport')?.clientWidth>720)revealSelectedNode();break;case'focus-script-scene':focusScriptScene(arg);break;case'review-script-changes':openScriptPendingReview();break;case'keep-script-output':keepScriptOutput(arg);break;case'candidate-review':openCandidateReview(args[0],args[1]);break;case'candidate-prepare':prepareNodeCandidate(arg);break;case'candidate-create':commitNodeCandidate();break;case'candidate-adopt':adoptNodeCandidate(args[0],args[1]);revealSelectedNode();save();break;case'candidate-return':closeDialog();if(document.getElementById('viewport')?.clientWidth<=720)focusNode(arg);else selectNode(arg);break;case'focus-node':focusNode(arg);break;case'edit-node':if(nodeById(arg)?.kind==='story')openScriptWorkbench(arg);else{selectNode(arg,true);document.getElementById('node-prompt')?.focus({preventScroll:true})}break;case'story-focus':focusNode(arg);break;case'save-work-preferences':S.workPreferences={preview:document.getElementById('pref-preview').checked,reuse:document.getElementById('pref-reuse').checked,confirm:document.getElementById('pref-confirm').checked};closeDialog();save();toast('制作偏好已保存');break;case'plan-import':{const file=document.getElementById('starting-file').files[0];const text=document.getElementById('starting-text').value.trim();S.drafts.shared=text||(file?'参考材料：'+file.name:'');closeDialog();render();prepareWorkPlan('drama');break;}case'work-preferences':workPreferences();break;case'import-start':importStartingPoint(arg);break;case'switch-work-plan':prepareWorkPlan(arg);break;case'plan-template':prepareWorkPlan(arg);break;case'enter-work-plan':enterWorkPlan(arg);break;case'story-play':playStory(arg);break;case'save-choice':saveStoryChoice();break;case'toggle-theme':S.theme=S.theme==='dark'?'light':'dark';render();break;case'open-example':rememberProject();loadStudioExample(arg,arg==='blank');break;case'resume-project':{rememberProject();const draft=S.projectDrafts[arg];if(draft){Object.assign(S,structuredClone(draft));S.referenceProjectEdit=structuredClone(draft.referenceProjectEdit??null);S.referenceCreationSpec=structuredClone(draft.referenceCreationSpec??null);S.referenceSourceScript=structuredClone(draft.referenceSourceScript??null);S.referenceCanvasViews=structuredClone(draft.referenceCanvasViews??[]);S.referenceGroupNames=structuredClone(draft.referenceGroupNames??{});S.referenceGroups=structuredClone(draft.referenceGroups??null);S.referenceTagCatalog=structuredClone(draft.referenceTagCatalog??null);S.referenceBoard=structuredClone(draft.referenceBoard??null);S.nodeDrafts=structuredClone(draft.nodeDrafts||{});S.canvasRedo=structuredClone(draft.canvasRedo||[]);S.canvasUndo=structuredClone(draft.canvasUndo||draft.history?.filter(h=>(h.id&&Number.isFinite(h.x)&&Number.isFinite(h.y))||h.type==='layout')||[]);S.goal=S.projectKind;S.screen='canvas';S.panel=null;S.selected=null;location.hash='canvas';render()}break;}case'all-tools':toolDirectory();break;case'tool-directory':toolDirectory(arg);break;case'tool-example':closeDialog();rememberProject();loadStudioExample(arg);break;case'preview-properties':closeDialog();focusNode(arg);break;case'tool':showStudioTool(arg);break;case'confirm-tool-demo':confirmStudioTool();break;case'review-project':reviewStudioProject();break;case'confirm-project-demo':finishStudioProject();break;case'home':rememberProject();S.screen='home';location.hash='';render();break;case'projects':if(S.screen==='canvas'){S.screen='home';location.hash='';render();setTimeout(()=>document.getElementById('project-grid')?.scrollIntoView({behavior:'smooth'}),30)}else document.getElementById('project-grid')?.scrollIntoView({behavior:'smooth'});break;case'open-project':openProject();break;case'start':{S.drafts.shared=document.getElementById('idea-input')?.value?.trim()||'';prepareWorkPlan('drama');break;}case'assets':case'templates':case'experts':library(key);break;case'features':features();break;case'settings':settings();break;case'ecosystem':showDialog('同一个 CrewON 生态',`<p>Studio 是 CrewON 的专业创作空间。正式产品将共用身份、项目、专家、工具箱、任务记录与权限。</p><div class="feature-list">${[['people','创作专家','编剧、导演、美术与剪辑，由导演助手统筹。'],['layers','工具与生成服务','复用已配置能力，普通用户选择效果与成本档位。'],['history','项目与制作记录','从对话进入工作室，继续同一个项目。']].map(([i,t,d])=>`<div class="feature-row">${I(i)}<div><h3>${t}</h3><p>${d}</p></div></div>`).join('')}</div>`,btn('明白了','close-modal','primary'));break;case'help':showDialog('让画布跟着你的思路走',`<p>节点是你的剧本、角色和镜头。导演助手会先整理好，你可以从任何一个部分开始调整。</p><div class="help-grid"><div>移动节点<kbd>拖动标题栏</kbd></div><div>平移画布<kbd>拖动空白处</kbd></div><div>精确缩放<kbd>⌘ / Ctrl + 滚轮</kbd></div><div>适应全部<kbd>F</kbd></div><div>建立引用<kbd>拖动或依次点击两侧连接点</kbd></div><div>断开引用<kbd>选中连线后 Delete / ⌫</kbd></div><div>撤销 / 重做<kbd>⌘ / Ctrl + Z / Shift + Z</kbd></div><div>返回 / 关闭<kbd>Esc</kbd></div></div>`,`${btn('重新体验示例','reset-demo','outline')}${btn('开始体验','close-modal','primary')}`);break;case'reset-demo':{const kind=S.projectKind;closeDialog();rememberProject();loadStudioExample(kind,true);toast('已打开新的示例，原草稿已保留');break;}case'director':S.panel=S.panel==='director'?null:'director';S.selected=null;render();break;case'close-panel':S.panel=null;render();break;case'select':selectNode(arg,true);break;case'select-shot2':closeDialog();focusNode('shot2');break;case'fit':S.scene='all';if(S.view!=='canvas'){S.view='canvas';render()}fitCanvas(true);break;case'scene-one':case'scene-two':{const scene=studioScriptScenes()[key==='scene-one'?0:1];if(scene)focusScriptScene(scene.id);break;}case'zoom-in':zoomBy(1.15);break;case'zoom-out':zoomBy(1/1.15);break;case'reset-zoom':zoomBy(1/S.zoom);break;case'tool-select':S.mode='select';render();break;case'tool-pan':S.mode='pan';render();break;case'add-node':showAdd();break;case'layout':studioRecordCanvasHistory({type:'layout',nodes:S.nodes.map(n=>({id:n.id,x:n.x,y:n.y}))});for(const n of S.nodes){const original=(S.layoutBase||initialNodes).find(o=>o.id===n.id);if(original){n.x=original.x;n.y=original.y}}render();fitCanvas(false);toast('画布已按当前制作方案整理');break;case'undo':case'redo':{const result=studioReplayCanvasHistory(key==='redo');if(result.ok){render();save();toast(key==='redo'?'已重做画布操作':'已撤销画布操作')}else toast(result.error);break}case'duplicate':{S.canvasRedo=[];const original=nodeById(arg);if(!original)break;const id=studioScriptId('copy'),n=original.kind==='story'?forkStudioScriptNode(original,id):structuredClone(original);n.id=id;if(original.kind!=='story')n.title+=' · 副本';n.x+=40;n.y+=55;S.nodes.push(n);if(Array.isArray(n.assetReferences))for(const ref of n.assetReferences)S.edges.push([ref.sourceId,n.id]);S.selected=n.id;S.panel='selection';render();revealSelectedNode();save();toast(original.kind==='story'?'已复制独立剧本，原镜头保持不变':'已复制节点');break}case'versions':openCandidateReview(arg);break;case'next-stage':if(S.videoReady)exportDialog();else approval(S.approved?'video':'preview');break;case'approve-preview':approval('preview');break;case'approve-video':approval('video');break;case'run-preview':runSimulation('preview');break;case'run-video':runSimulation('video');break;case'budget':showDialog('先把作品做好，也把成本管好',`<div class="approval-items"><div class="approval-item">${I('image')}角色、场景与关键帧<span>¥3.20</span></div><div class="approval-item">${I('film')}视频与配音<span>¥15.40</span></div><div class="approval-item">${I('layers')}本地剪辑与导出<span>复用已有素材</span></div></div><div class="cost-box"><small>本集估算 · 预算上限 ¥30</small><strong>¥18.60</strong></div><p style="margin-top:15px">以上均为演示数字。正式产品按实际服务与模型估算，受理状态不明时暂停，不自动重复计费。</p>`,btn('继续创作','close-modal','primary'));break;case'timeline':S.timeline=!S.timeline;render();revealSelectedNode();save();break;case'preview':S.projectKind==='interactive'?playStory():S.projectKind==='drama'?preview():previewStudioContent();break;case'toggle-play':togglePreview();break;case'preview-edit':closeDialog();S.timeline=true;S.panel=null;render();break;case'export':S.projectKind==='drama'?exportDialog():deliverStudioContent();break;case'simulate-export':closeDialog();showDialog('演示成片已就绪',`<p>这里展示真实产品的交付状态。示例中的画面、候选、费用与处理进度均为交互演示。</p><div class="cost-box"><small>${esc(S.project)} · 第 1 集<br>${S.clips.length} 镜头 · ${projectDuration()} 秒 · 16:9</small><strong style="font-size:17px">可继续编辑</strong></div>`,`${btn('回到工作室','close-modal','outline')}${btn('下载制作方案','download-plan','primary','download')}`);break;case'download-plan':{const payload={product:'CrewON Studio',prototype:true,project:S.project,brief:S.history.filter(h=>h.type==='brief'),nodes:S.nodes,edges:S.edges,clips:S.clips,history:S.history,note:'设计演示数据，不含生成视频与真实计费'};const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='CrewON-Studio-制作方案.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),500);toast('已下载示例制作方案');break}case'close-modal':closeDialog();break;case'template':closeDialog();S.project=arg==='城市雨夜'?'雨停之前':'末班灯';openProject();toast('已套用「'+arg+'」的示例创作结构');break;case'import-asset':closeDialog();if(S.screen!=='canvas')openProject();addNode(arg==='旧站台'||arg==='雨巷'||arg==='街口'?'scene':'character',arg);break;case'add-expert':toast('已将'+arg+'加入示例创作团队');break;case'upload':showDialog('导入你的创作材料',`<div class="asset-import">${I('upload')}<p style="margin-top:9px">上传剧本、小说片段或参考图片</p><input type="file" id="demo-file" accept=".txt,.md,.png,.jpg,.jpeg,.webp" style="margin-top:16px;font-size:11px;max-width:100%"></div><p>本 Demo 仅在浏览器本地读取文件名，不上传到服务器。</p>`,`${btn('取消','close-modal','outline')}${btn('使用所选材料','import-file','primary')}`);break;case'import-file':{const file=document.getElementById('demo-file')?.files[0];if(!file){toast('请先选择一个文件');return}S.history.push({type:'import',name:file.name});closeDialog();if(S.screen==='home'){S.intake='script';S.drafts.shared='已选择参考材料：'+file.name;render()}else toast('已选择 '+file.name+'，正式版会在这里解析参考材料');break}case'save-node':{const n=nodeById(S.selected);if(!n)return;n.prompt=document.getElementById('node-prompt')?.value??n.prompt;if(['text','note'].includes(n.kind))n.text=n.prompt;n.description=n.kind==='shot'?n.description:n.prompt.slice(0,50);n.dialogue=document.getElementById('node-dialogue')?.value??n.dialogue;n.seconds=Number(document.getElementById('node-duration')?.value)||n.seconds;n.motion=document.getElementById('node-motion')?.value||n.motion;n.creationPreferences={...n.creationPreferences,...Object.fromEntries(Object.entries(S.nodeDrafts[n.id]||{}).filter(([key])=>key.startsWith('creation')||key==='toolDrafts'))};delete S.nodeDrafts[n.id];recordNodeInputEdit(n);S.revision++;render();toast('编辑输入已保存，采用结果与候选保持不变');break}case'regenerate':case'run-single':prepareNodeCandidate(S.selected);break;case'suggest-warm':focusNode('shot2');toast('已定位递灯镜头，可以调整画面和动作');break;case'history':projectHistoryDialog();break;case'audio':showDialog('声音，让情绪连起来',`<label class="field">对白声音<select><option>林晚 · 温柔自然</option><option>旁白 · 温暖克制</option></select></label><label class="field">环境声音量<input type="range" min="0" max="100" value="28" aria-label="环境声音量"></label><label class="field">字幕样式<select><option>简洁白字 · 底部居中</option><option>无字幕</option></select></label><p>声音绑定与混音的样式示意，不处理真实音频。</p>`,btn('应用到示例','audio-done','primary'));break;case'audio-done':closeDialog();toast('已应用示例声音与字幕设置');break;default:toast('此能力已纳入产品设计范围')}}
window.addEventListener('resize',()=>{if(S.screen==='canvas'){applyCamera();revealSelectedNode();save()}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&drag){event.preventDefault();event.stopImmediatePropagation();cancelCanvasDrag()}},true);
window.addEventListener('blur',()=>{spaceDown=false;cancelCanvasDrag()});
if(new URLSearchParams(location.search).get('entry')!=='1')window.addEventListener('pagehide',persist);
render();if(S.screen==='canvas'&&!stored.pan)setTimeout(()=>fitCanvas(false),60);

document.addEventListener('dblclick',event=>{const node=event.target.closest('[data-node]');if(node&&!event.target.closest('button')){if(canvasCreationNode())handleCanvasCreationAction('canvas-creation-expand');else handleAction('edit-node:'+node.dataset.node);}});
document.addEventListener('click',event=>{document.querySelectorAll('.node-more[open]').forEach(el=>{if(!el.contains(event.target))el.open=false;});});

window.addEventListener('resize',positionSelectionToolbar);

document.addEventListener('click',event=>{const vp=document.getElementById('viewport');if(!vp||!vp.contains(event.target)||vp.dataset.dragged||drag||event.target.closest('.node,.selection-toolbar,.canvas-creation,.floating-tools,.canvas-bottom,.canvas-link-panel,.canvas-link-hit,.storyboard-list,button,summary'))return;if(canvasSelectedLink){canvasSelectedLink=null;drawEdges();}if(S.selected){S.selected=null;if(S.panel==='selection')S.panel=null;render();}});
